		<div class="msrwa-card"><h2>Sorties image</h2><div class="msrwa-fields"><label>Ratio image principale<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[featured_ratio]"><?php foreach ( array( '1:1', '4:5', '3:2', '2:3' ) as $ratio ) : ?><option value="<?php echo esc_attr( $ratio ); ?>" <?php selected( $s['featured_ratio'], $ratio ); ?>><?php echo esc_html( $ratio ); ?></option><?php endforeach; ?></select></label><label>Ratio Facebook<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[facebook_ratio]"><?php foreach ( array( '4:5', '1:1', '2:3', '3:2' ) as $ratio ) : ?><option value="<?php echo esc_attr( $ratio ); ?>" <?php selected( $s['facebook_ratio'], $ratio ); ?>><?php echo esc_html( $ratio ); ?></option><?php endforeach; ?></select></label><label>Qualité OpenAI<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[image_quality]"><?php foreach ( array( 'low', 'medium', 'high', 'xhigh', 'max', 'auto' ) as $quality ) : ?><option value="<?php echo esc_attr( $quality ); ?>" <?php selected( $s['image_quality'], $quality ); ?>><?php echo esc_html( $quality ); ?></option><?php endforeach; ?></select></label><label>Format de sortie OpenAI<select name="<?php echo esc_attr( MSRWA_Settings::OPTION ); ?>[image_format]"><?php foreach ( array( 'webp', 'jpeg', 'png' ) as $format ) : ?><option value="<?php echo esc_attr( $format ); ?>" <?php selected( $s['image_format'], $format ); ?>><?php echo esc_html( $format ); ?></option><?php endforeach; ?></select></label></div><p class="description">Les formats et qualités natifs dépendent du fournisseur. Le recadrage conserve le fichier final dans le format choisi sans étirer l’image.</p></div>
